/**
 * Screen #27 — Available / Alternative Slot Selection
 * Displays complete system-generated candidates.
 *
 * AUTHORITATIVE M3 INVARIANTS:
 * - Each candidate is an INDIVISIBLE bundle: Time Slot + Qualified Therapist + Compatible Room.
 * - Selecting a candidate does NOT reserve any resource or create a session.
 * - Handles No-Availability cleanly, showing alternative candidates generated by backend engine.
 * - BR-M3-08: Supports rejecting individual alternatives, successive negotiation turns,
 *   declining all alternatives, detecting exhaustion, and finalizing session cancellation.
 * - Race-Safe: Uses request sequence tokens to discard stale out-of-order async responses.
 * - Negotiation-Isolated: Resets rejection list when search parameters change.
 */

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useCustomer } from '../../context/CustomerContext';
import { spaApi } from '../../features/m3-spa/api/spaApi';
import type { SchedulingCandidate, CandidateGenerationResult } from '../../features/m3-spa/types/spaTypes';
import { getResortTodayString } from '../../features/m3-spa/utils/spaDateUtils';
import {
  ChevronLeft,
  Clock,
  User,
  MapPin,
  Calendar,
  Sparkles,
  Check,
  AlertCircle,
  ArrowRight,
  RotateCcw,
  RefreshCw,
  XCircle,
  CheckCircle,
  ArrowUpDown,
} from 'lucide-react';

interface NavigationState {
  result?: CandidateGenerationResult;
  treatmentId?: number;
  treatmentName?: string;
  durationMinutes?: number;
  preferredDate?: string;
  timeRangePreference?: string;
  customerNote?: string;
  rescheduleSessionId?: number;
}

export const SpaAlternativeSlotsPage: React.FC = () => {
  const { t } = useTranslation('customer');
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const { activeBooking } = useCustomer();

  const navState = (location.state as NavigationState) || {};
  const treatmentIdFromQuery = searchParams.get('treatment') ? Number(searchParams.get('treatment')) : 1;
  const dateFromQuery = searchParams.get('date') || getResortTodayString();

  const [candidates, setCandidates] = useState<SchedulingCandidate[]>(navState.result?.candidates || []);
  const [alternativeCandidates, setAlternativeCandidates] = useState<SchedulingCandidate[]>(
    navState.result?.alternativeCandidates || []
  );
  const [selectedCandidate, setSelectedCandidate] = useState<SchedulingCandidate | null>(null);
  const [rejectedCandidateIds, setRejectedCandidateIds] = useState<string[]>([]);
  const [filterTimeOfDay, setFilterTimeOfDay] = useState<'ALL' | 'MORNING' | 'AFTERNOON' | 'EVENING'>('ALL');
  const [selectedTherapistId, setSelectedTherapistId] = useState<number | 'ALL'>('ALL');
  const [selectedRoomId, setSelectedRoomId] = useState<number | 'ALL'>('ALL');
  const [scoreFilter, setScoreFilter] = useState<'ALL' | 'EXCELLENT' | 'GOOD' | 'FAIR' | 'BELOW'>('ALL');
  const [treatmentRooms, setTreatmentRooms] = useState<{ id: number; name: string }[]>([]);
  const [sortBy, setSortBy] = useState<'RECOMMENDED' | 'EARLIEST'>('RECOMMENDED');
  const [visibleCount, setVisibleCount] = useState<number>(6);
  const [loading, setLoading] = useState<boolean>(!navState.result);
  const [cancelling, setCancelling] = useState<boolean>(false);
  const [cancellationComplete, setCancellationComplete] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Request sequence token to prevent out-of-order asynchronous responses from overwriting newer state
  const requestIdRef = useRef<number>(0);

  const treatmentId = navState.treatmentId || treatmentIdFromQuery;
  const preferredDate = navState.preferredDate || dateFromQuery;
  const rescheduleSessionId = navState.rescheduleSessionId;
  const customerNote = navState.customerNote;

  const todayStr = useMemo(() => getResortTodayString(), []);

  // Strict stay date bounds (Task E)
  const minDate = useMemo(() => {
    if (activeBooking?.startDate && activeBooking.startDate > todayStr) {
      return activeBooking.startDate;
    }
    return todayStr;
  }, [activeBooking?.startDate, todayStr]);

  const maxDate = useMemo(() => {
    return activeBooking?.endDate || undefined;
  }, [activeBooking?.endDate]);

  const initialDate = useMemo(() => {
    let d = preferredDate && preferredDate >= minDate ? preferredDate : minDate;
    if (maxDate && d > maxDate) {
      d = maxDate;
    }
    return d;
  }, [preferredDate, minDate, maxDate]);

  const [currentDate, setCurrentDate] = useState<string>(initialDate);

  // Load treatment room inventory from API so all 9 rooms are dynamically available in filter
  useEffect(() => {
    let active = true;
    spaApi
      .getTreatmentRooms()
      .then((rooms) => {
        if (!active || !rooms) return;
        setTreatmentRooms(rooms.map((r) => ({ id: r.roomId, name: r.roomName })));
      })
      .catch(() => {
        // Fallback to candidates room extraction
      });
    return () => {
      active = false;
    };
  }, []);

  // Dynamic filter lists extracted from candidates & backend inventory
  const availableTherapists = useMemo(() => {
    const map = new Map<number, string>();
    candidates.forEach((c) => map.set(c.therapistId, c.therapistName));
    alternativeCandidates.forEach((c) => map.set(c.therapistId, c.therapistName));
    return Array.from(map.entries()).map(([id, name]) => ({ id, name }));
  }, [candidates, alternativeCandidates]);

  const availableSuites = useMemo(() => {
    const map = new Map<number, string>();
    treatmentRooms.forEach((r) => map.set(r.id, r.name));
    candidates.forEach((c) => map.set(c.roomId, c.roomName));
    alternativeCandidates.forEach((c) => map.set(c.roomId, c.roomName));
    return Array.from(map.entries()).map(([id, name]) => ({ id, name }));
  }, [treatmentRooms, candidates, alternativeCandidates]);

  // Date switching handler (strictly bounded by retreat stay)
  const handleDateChange = (newDate: string) => {
    if (!newDate || newDate === currentDate) return;
    if (newDate < todayStr) {
      setError(t('spa.pastDateNotAllowed', 'Cannot search or book spa slots in the past.'));
      return;
    }
    if (activeBooking?.startDate && newDate < activeBooking.startDate) {
      setError(t('spa.stayBoundaryBefore', `Selected date is before your retreat stay check-in date (${activeBooking.startDate}).`));
      return;
    }
    if (activeBooking?.endDate && newDate > activeBooking.endDate) {
      setError(t('spa.stayBoundaryExceeded', `Selected date (${newDate}) falls outside your retreat stay period (${activeBooking.startDate} to ${activeBooking.endDate}).`));
      return;
    }
    setCurrentDate(newDate);
    setRejectedCandidateIds([]);
    setSelectedCandidate(null);
    setVisibleCount(6);
    const currentReqId = ++requestIdRef.current;
    setLoading(true);
    setError(null);
    spaApi
      .generateCandidates({
        treatmentId,
        preferredDate: newDate,
        flexibleWithDate: true,
        rescheduleSessionId,
      })
      .then((res) => {
        if (currentReqId !== requestIdRef.current) return;
        setCandidates(res.candidates || []);
        setAlternativeCandidates(res.alternativeCandidates || []);
      })
      .catch((err) => {
        if (currentReqId !== requestIdRef.current) return;
        setError(err instanceof Error ? err.message : 'Failed to retrieve available slots for selected date.');
      })
      .finally(() => {
        if (currentReqId === requestIdRef.current) {
          setLoading(false);
        }
      });
  };

  const handleResetFilters = () => {
    setFilterTimeOfDay('ALL');
    setSelectedTherapistId('ALL');
    setSelectedRoomId('ALL');
    setScoreFilter('ALL');
    setSortBy('RECOMMENDED');
    setVisibleCount(6);
  };

  const hasActiveFilters =
    filterTimeOfDay !== 'ALL' ||
    selectedTherapistId !== 'ALL' ||
    selectedRoomId !== 'ALL' ||
    scoreFilter !== 'ALL' ||
    sortBy !== 'RECOMMENDED';

  const filteredAndSortedCandidates = useMemo(() => {
    let list = candidates.filter((c) => {
      // Time of day
      if (filterTimeOfDay !== 'ALL') {
        const hour = parseInt(c.startTime.split(':')[0], 10);
        if (filterTimeOfDay === 'MORNING' && hour >= 12) return false;
        if (filterTimeOfDay === 'AFTERNOON' && (hour < 12 || hour >= 17)) return false;
        if (filterTimeOfDay === 'EVENING' && hour < 17) return false;
      }
      // Therapist
      if (selectedTherapistId !== 'ALL' && c.therapistId !== selectedTherapistId) {
        return false;
      }
      // Room/Suite
      if (selectedRoomId !== 'ALL' && c.roomId !== selectedRoomId) {
        return false;
      }
      // Recommendation Score
      if (scoreFilter !== 'ALL') {
        const score = c.recommendationScore ?? 0;
        if (scoreFilter === 'EXCELLENT' && score < 90) return false;
        if (scoreFilter === 'GOOD' && (score < 80 || score >= 90)) return false;
        if (scoreFilter === 'FAIR' && (score < 70 || score >= 80)) return false;
        if (scoreFilter === 'BELOW' && score >= 70) return false;
      }
      return true;
    });

    if (sortBy === 'EARLIEST') {
      list = [...list].sort((a, b) => a.startTime.localeCompare(b.startTime));
    }

    return list;
  }, [candidates, filterTimeOfDay, selectedTherapistId, selectedRoomId, scoreFilter, sortBy]);

  const visibleCandidates = filteredAndSortedCandidates.slice(0, visibleCount);
  const hasMore = visibleCount < filteredAndSortedCandidates.length;

  // Negotiation Isolation: Reset rejection memory if treatment or search date changes
  useEffect(() => {
    setRejectedCandidateIds([]);
    setSelectedCandidate(null);
  }, [treatmentId, preferredDate]);

  // If page was loaded directly without navigation state, fetch candidates from backend API
  useEffect(() => {
    if (!navState.result) {
      if (preferredDate && preferredDate < todayStr) {
        setError(t('spa.pastDateNotAllowed', 'Cannot search or book spa slots in the past.'));
        setLoading(false);
        return;
      }
      const currentReqId = ++requestIdRef.current;
      setLoading(true);
      spaApi
        .generateCandidates({
          treatmentId,
          preferredDate: initialDate,
          flexibleWithDate: true,
          rescheduleSessionId,
        })
        .then((res) => {
          if (currentReqId !== requestIdRef.current) return; // Discard stale out-of-order response
          setCandidates(res.candidates || []);
          setAlternativeCandidates(res.alternativeCandidates || []);
        })
        .catch((err) => {
          if (currentReqId !== requestIdRef.current) return;
          setError(err instanceof Error ? err.message : 'Failed to retrieve available slots.');
        })
        .finally(() => {
          if (currentReqId === requestIdRef.current) {
            setLoading(false);
          }
        });
    }
  }, [navState.result, treatmentId, preferredDate, rescheduleSessionId]);

  /**
   * Reject an individual candidate bundle (BR-M3-08).
   * Accumulates rejectedCandidateIds, filters UI, and re-queries backend if visible pool is emptied.
   */
  const handleRejectCandidate = async (candidateId: string) => {
    const updatedRejected = [...rejectedCandidateIds, candidateId];
    setRejectedCandidateIds(updatedRejected);

    if (selectedCandidate?.candidateId === candidateId) {
      setSelectedCandidate(null);
    }

    const remainingCandidates = candidates.filter((c) => c.candidateId !== candidateId);
    const remainingAlternatives = alternativeCandidates.filter((c) => c.candidateId !== candidateId);
    setCandidates(remainingCandidates);
    setAlternativeCandidates(remainingAlternatives);

    // If both active pools are exhausted after rejection, re-query engine with excluded candidate IDs
    if (remainingCandidates.length === 0 && remainingAlternatives.length === 0) {
      const currentReqId = ++requestIdRef.current;
      setLoading(true);
      setError(null);
      try {
        const res = await spaApi.generateCandidates({
          treatmentId,
          preferredDate,
          flexibleWithDate: true,
          rejectedCandidateIds: updatedRejected,
          rescheduleSessionId,
        });
        if (currentReqId !== requestIdRef.current) return; // Discard stale out-of-order response
        setCandidates(res.candidates || []);
        setAlternativeCandidates(res.alternativeCandidates || []);
      } catch (err) {
        if (currentReqId !== requestIdRef.current) return;
        setError(err instanceof Error ? err.message : 'Failed to query scheduling engine for next alternatives.');
      } finally {
        if (currentReqId === requestIdRef.current) {
          setLoading(false);
        }
      }
    }
  };

  /**
   * Decline all alternatives or cancel when alternatives are exhausted (BR-M3-08).
   * Flow A (New booking): Safe client-side abandonment (navigates back to catalogue with 0 database changes).
   * Flow B (Reschedule): Server cancellation of persistent session (idempotent, frees resource locks).
   */
  const handleDeclineAllAlternatives = async () => {
    if (rescheduleSessionId) {
      setCancelling(true);
      setError(null);
      try {
        await spaApi.cancelSession(rescheduleSessionId);
        setCancellationComplete(true);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to cancel session on server.');
      } finally {
        setCancelling(false);
      }
    } else {
      // Flow A: New booking negotiation declined by customer: cleanly return to Spa Booking with treatment and criteria preserved
      navigate(`/customer/spa/book?treatment=${treatmentId}`, {
        state: {
          preferredDate: currentDate,
          customerNote,
          fromDeclineAll: true,
        },
      });
    }
  };

  const handleSelectAndProceed = () => {
    if (!selectedCandidate) return;

    const retreatBookingId = activeBooking?.id
      ? parseInt(String(activeBooking.id).replace(/\D/g, ''), 10)
      : (navState as any).retreatBookingId;

    // Navigate to Screen 28 (Final Confirmation)
    navigate('/customer/spa/confirmation', {
      state: {
        selectedCandidate,
        treatmentId,
        rescheduleSessionId,
        customerNote,
        retreatBookingId,
        bookingReference: activeBooking?.bookingReference || (navState as any).bookingReference,
      },
    });
  };

  const isExhausted = !loading && candidates.length === 0 && alternativeCandidates.length === 0;

  if (cancellationComplete) {
    return (
      <div className="spa-alternative-slots-page" id="screen-27-cancellation-confirmed" style={{ maxWidth: '650px', margin: '40px auto', padding: '24px' }}>
        <div
          style={{
            backgroundColor: '#fff',
            border: '1px solid #e2e8f0',
            borderRadius: '12px',
            padding: '36px 24px',
            textAlign: 'center',
            boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
          }}
        >
          <CheckCircle size={48} style={{ color: '#059669', margin: '0 auto 16px' }} />
          <h2 style={{ fontSize: '22px', fontWeight: 700, color: '#0f172a', marginBottom: '8px' }}>
            {t('spa.sessionCancelledTitle', 'Session Cancelled')}
          </h2>
          <p style={{ color: '#64748b', fontSize: '15px', lineHeight: 1.5, marginBottom: '24px' }}>
            {t(
              'spa.sessionCancelledDesc',
              'Your spa reservation has been officially cancelled following the decline of all offered alternatives. No resources remain reserved.'
            )}
          </p>
          <div style={{ display: 'flex', gap: '12px', justifyContent: 'center' }}>
            <button
              id="btn-view-my-sessions"
              className="hsw-btn hsw-btn-primary"
              onClick={() => navigate('/customer/spa/my-sessions')}
              style={{ padding: '10px 20px', fontWeight: 600 }}
            >
              {t('spa.viewMySessions', 'View My Sessions')}
            </button>
            <button
              id="btn-back-to-treatments"
              className="hsw-btn hsw-btn-secondary"
              onClick={() => navigate('/customer/spa')}
              style={{ padding: '10px 20px' }}
            >
              {t('spa.browseTreatments', 'Browse Treatments')}
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="spa-alternative-slots-page" id="screen-27-available-slots">
      {/* Header */}
      <div className="spa-alt-header">
        <button
          className="spa-back-btn"
          onClick={() =>
            navigate(
              `/customer/spa/book?treatment=${treatmentId}${
                rescheduleSessionId ? `&reschedule=${rescheduleSessionId}` : ''
              }`
            )
          }
          id="btn-back-to-preferences"
        >
          <ChevronLeft size={18} />
          <span>{t('spa.modifyCriteria', 'Modify Search Criteria')}</span>
        </button>
        <h1>{t('spa.candidateSelectionTitle', 'Available Scheduling Candidates')}</h1>
        <p className="spa-alt-subtitle">
          {t(
            'spa.candidateBundleExplanation',
            'Each option below is an indivisible bundle combining an open time slot, a certified practitioner, and a compatible treatment suite.'
          )}
        </p>
      </div>

      {rescheduleSessionId && (
        <div
          style={{
            backgroundColor: '#eff6ff',
            border: '1px solid #bfdbfe',
            borderRadius: '8px',
            padding: '12px 16px',
            marginBottom: '20px',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            color: '#1e40af',
          }}
        >
          <RotateCcw size={18} />
          <span>
            {t(
              'spa.rescheduleSelectingNotice',
              'Selecting a replacement candidate will not alter your current booking until you confirm on the final screen.'
            )}
          </span>
        </div>
      )}

      {loading && (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: '#64748b' }}>
          <RefreshCw size={32} className="spin" style={{ animation: 'spin 1s linear infinite' }} />
          <p style={{ marginTop: '12px' }}>{t('spa.queryingEngine', 'Consulting scheduling engine...')}</p>
        </div>
      )}

      {error && (
        <div
          style={{
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            borderRadius: '8px',
            padding: '16px',
            color: '#b91c1c',
            marginBottom: '20px',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
          }}
        >
          <AlertCircle size={20} />
          <span>{error}</span>
        </div>
      )}

      {!loading && !error && (
        <div className="spa-alt-layout">
          <div className="spa-alt-main">
            {/* Recommendation Explanation Banner */}
            {candidates.length > 0 && (
              <div className="spa-recommendation-banner" style={{
                backgroundColor: '#f0fdf4',
                border: '1px solid #bbf7d0',
                borderRadius: '8px',
                padding: '12px 16px',
                marginBottom: '16px',
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                color: '#166534',
                fontSize: '13px'
              }}>
                <Sparkles size={18} style={{ color: '#16a34a', flexShrink: 0 }} />
                <div>
                  <strong>{t('spa.recommendationTitle', 'Engine Recommendation Active:')}</strong>{' '}
                  {t('spa.recommendationDesc', 'Top slot is calibrated for practitioner qualification, suite compatibility, and mandatory 15-minute buffer.')}
                </div>
              </div>
            )}

            {/* Filter and Control Bar (Phase D: Date, Time, Therapist, Suite, Sort, Clear) */}
            {candidates.length > 0 && (
              <div
                className="spa-filter-bar"
                id="spa-alternatives-filter-bar"
                style={{
                  backgroundColor: '#f8fafc',
                  border: '1px solid #e2e8f0',
                  borderRadius: '12px',
                  padding: '16px',
                  marginBottom: '20px',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '12px',
                }}
              >
                {/* Top Row: Date Switcher & Time Period Pills */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '12px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <Calendar size={16} style={{ color: '#0d9488' }} />
                    <label htmlFor="spa-alt-date-picker" style={{ fontSize: '13px', fontWeight: 600, color: '#334155' }}>
                      {t('spa.targetDate', 'Target Date')}:
                    </label>
                    <input
                      id="spa-alt-date-picker"
                      type="date"
                      min={minDate}
                      max={maxDate}
                      value={currentDate}
                      onChange={(e) => handleDateChange(e.target.value)}
                      style={{
                        padding: '6px 10px',
                        borderRadius: '6px',
                        border: '1px solid #cbd5e1',
                        fontSize: '13px',
                        color: '#0f172a',
                        backgroundColor: '#fff',
                      }}
                    />
                  </div>

                  {/* Time Filter Pills */}
                  <div className="spa-filter-pills" style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                    {(['ALL', 'MORNING', 'AFTERNOON', 'EVENING'] as const).map((period) => (
                      <button
                        key={period}
                        type="button"
                        onClick={() => setFilterTimeOfDay(period)}
                        id={`filter-period-${period.toLowerCase()}`}
                        style={{
                          padding: '5px 12px',
                          borderRadius: '16px',
                          border: filterTimeOfDay === period ? '1px solid #0d9488' : '1px solid #cbd5e1',
                          backgroundColor: filterTimeOfDay === period ? '#0d9488' : '#fff',
                          color: filterTimeOfDay === period ? '#fff' : '#475569',
                          fontSize: '12px',
                          fontWeight: 600,
                          cursor: 'pointer',
                          transition: 'all 0.15s ease',
                        }}
                      >
                        {period === 'ALL' && t('spa.filterAll', 'All Times')}
                        {period === 'MORNING' && t('spa.filterMorning', 'Morning (<12:00)')}
                        {period === 'AFTERNOON' && t('spa.filterAfternoon', 'Afternoon (12:00–17:00)')}
                        {period === 'EVENING' && t('spa.filterEvening', 'Evening (≥17:00)')}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Bottom Row: Therapist, Suite, Sort, and Clear */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '10px', paddingTop: '8px', borderTop: '1px solid #edf2f7' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
                    {/* Therapist filter */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <User size={15} style={{ color: '#64748b' }} />
                      <select
                        id="spa-filter-therapist"
                        value={selectedTherapistId}
                        onChange={(e) => setSelectedTherapistId(e.target.value === 'ALL' ? 'ALL' : Number(e.target.value))}
                        style={{
                          padding: '5px 10px',
                          borderRadius: '6px',
                          border: '1px solid #cbd5e1',
                          fontSize: '12px',
                          backgroundColor: '#fff',
                          color: '#334155',
                        }}
                      >
                        <option value="ALL">{t('spa.allTherapists', 'All Therapists')}</option>
                        {availableTherapists.map((th) => (
                          <option key={th.id} value={th.id}>
                            {th.name}
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Suite filter */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <MapPin size={15} style={{ color: '#64748b' }} />
                      <select
                        id="spa-filter-suite"
                        value={selectedRoomId}
                        onChange={(e) => setSelectedRoomId(e.target.value === 'ALL' ? 'ALL' : Number(e.target.value))}
                        style={{
                          padding: '5px 10px',
                          borderRadius: '6px',
                          border: '1px solid #cbd5e1',
                          fontSize: '12px',
                          backgroundColor: '#fff',
                          color: '#334155',
                        }}
                      >
                        <option value="ALL">{t('spa.allSuites', 'All Suites')}</option>
                        {availableSuites.map((rm) => (
                          <option key={rm.id} value={rm.id}>
                            {rm.name}
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Recommendation Score Quality filter */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <Sparkles size={15} style={{ color: '#0d9488' }} />
                      <select
                        id="spa-filter-score"
                        value={scoreFilter}
                        onChange={(e) => setScoreFilter(e.target.value as 'ALL' | 'EXCELLENT' | 'GOOD' | 'FAIR' | 'BELOW')}
                        style={{
                          padding: '5px 10px',
                          borderRadius: '6px',
                          border: '1px solid #cbd5e1',
                          fontSize: '12px',
                          backgroundColor: '#fff',
                          color: '#334155',
                        }}
                      >
                        <option value="ALL">{t('spa.allScores', 'Tất cả điểm đề xuất')}</option>
                        <option value="EXCELLENT">90–100 (Xuất sắc / Excellent)</option>
                        <option value="GOOD">80–89 (Tốt / Good)</option>
                        <option value="FAIR">70–79 (Khá / Fair)</option>
                        <option value="BELOW">&lt; 70 (Dưới ngưỡng / Below)</option>
                      </select>
                    </div>

                    {/* Sort selector */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      <ArrowUpDown size={15} style={{ color: '#64748b' }} />
                      <select
                        id="spa-filter-sort"
                        value={sortBy}
                        onChange={(e) => setSortBy(e.target.value as 'RECOMMENDED' | 'EARLIEST')}
                        style={{
                          padding: '5px 10px',
                          borderRadius: '6px',
                          border: '1px solid #cbd5e1',
                          fontSize: '12px',
                          backgroundColor: '#fff',
                          color: '#334155',
                        }}
                      >
                        <option value="RECOMMENDED">{t('spa.sortRecommended', 'AI Recommended (Optimal)')}</option>
                        <option value="EARLIEST">{t('spa.sortEarliest', 'Earliest Time First')}</option>
                      </select>
                    </div>
                  </div>

                  {/* Reset Filters */}
                  {hasActiveFilters && (
                    <button
                      type="button"
                      id="btn-reset-filters"
                      onClick={handleResetFilters}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '4px',
                        padding: '4px 10px',
                        borderRadius: '6px',
                        border: '1px solid #cbd5e1',
                        backgroundColor: '#fff',
                        color: '#64748b',
                        fontSize: '12px',
                        cursor: 'pointer',
                      }}
                    >
                      <RotateCcw size={13} />
                      <span>{t('spa.clearFilters', 'Clear Filters')}</span>
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* Primary Candidates Section */}
            {candidates.length > 0 && (
              <section className="spa-candidate-group">
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px', flexWrap: 'wrap', gap: '8px' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <Calendar size={18} style={{ color: '#0d9488' }} />
                    <h2 style={{ fontSize: '18px', fontWeight: 600, margin: 0 }}>
                      {t('spa.candidatesForDate', 'Open Slots for')} {currentDate} ({filteredAndSortedCandidates.length})
                    </h2>
                  </div>
                  {filteredAndSortedCandidates.length > visibleCount && (
                    <span style={{ fontSize: '12px', color: '#64748b' }}>
                      {t('spa.showingSlots', 'Showing')} 1–{visibleCandidates.length} {t('spa.ofTotal', 'of')} {filteredAndSortedCandidates.length}
                    </span>
                  )}
                </div>

                {filteredAndSortedCandidates.length === 0 ? (
                  <div
                    style={{
                      padding: '32px 16px',
                      textAlign: 'center',
                      backgroundColor: '#f8fafc',
                      borderRadius: '8px',
                      border: '1px dashed #cbd5e1',
                      color: '#64748b',
                    }}
                  >
                    <p style={{ margin: '0 0 10px', fontSize: '14px' }}>
                      {t('spa.noFilterMatches', 'No slots match the currently applied filters.')}
                    </p>
                    <button
                      type="button"
                      onClick={handleResetFilters}
                      className="hsw-btn hsw-btn-secondary"
                      style={{ padding: '6px 14px', fontSize: '12px' }}
                    >
                      {t('spa.clearFilters', 'Clear Filters')}
                    </button>
                  </div>
                ) : (
                  <div className="spa-candidates-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '16px' }}>
                    {visibleCandidates.map((c) => {
                      const isSelected = selectedCandidate?.candidateId === c.candidateId;
                      const isTopRecommendation = c.candidateId === candidates[0]?.candidateId;
                      return (
                        <div
                          key={c.candidateId}
                          className={`spa-candidate-card ${isSelected ? 'spa-candidate-card--selected' : ''}`}
                          onClick={() => setSelectedCandidate(c)}
                          id={`candidate-${c.candidateId}`}
                          style={{
                            border: isSelected ? '2px solid #0d9488' : isTopRecommendation ? '2px solid #f59e0b' : '1px solid #e2e8f0',
                            borderRadius: '10px',
                            padding: '16px',
                            cursor: 'pointer',
                            backgroundColor: isSelected ? '#f0fdfa' : isTopRecommendation ? '#fffbeb' : '#fff',
                            boxShadow: isSelected ? '0 4px 12px rgba(13, 148, 136, 0.15)' : isTopRecommendation ? '0 2px 8px rgba(245, 158, 11, 0.15)' : 'none',
                            transition: 'all 0.2s ease',
                            display: 'flex',
                            flexDirection: 'column',
                            justifyContent: 'space-between',
                          }}
                        >
                          <div>
                            {isTopRecommendation && (
                              <div style={{
                                display: 'inline-flex',
                                alignItems: 'center',
                                gap: '4px',
                                backgroundColor: '#fef3c7',
                                color: '#92400e',
                                fontSize: '11px',
                                fontWeight: 700,
                                padding: '3px 8px',
                                borderRadius: '12px',
                                marginBottom: '8px',
                                letterSpacing: '0.3px',
                              }}>
                                <Sparkles size={12} style={{ color: '#d97706' }} />
                                <span>{t('spa.recommendedForYou', 'Recommended for You')}</span>
                              </div>
                            )}
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '10px' }}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                <Clock size={16} style={{ color: '#0d9488' }} />
                                <span style={{ fontSize: '16px', fontWeight: 700, color: '#0f172a' }}>
                                  {c.startTime} – {c.endTime}
                                </span>
                              </div>
                              {isSelected && (
                                <span style={{ backgroundColor: '#0d9488', color: '#fff', borderRadius: '50%', padding: '2px', display: 'flex' }}>
                                  <Check size={14} />
                                </span>
                              )}
                            </div>

                            <div style={{ fontSize: '13px', color: '#475569', display: 'flex', flexDirection: 'column', gap: '6px' }}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                <User size={14} style={{ color: '#64748b' }} />
                                <span><strong>{t('spa.therapist', 'Therapist')}:</strong> {c.therapistName}</span>
                              </div>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                                <MapPin size={14} style={{ color: '#64748b' }} />
                                <span><strong>{t('spa.suite', 'Suite')}:</strong> {c.roomName}</span>
                              </div>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '12px', color: '#64748b', marginTop: '4px' }}>
                                <Sparkles size={13} style={{ color: '#0d9488' }} />
                                <span>{c.durationMinutes} {t('spa.minutes', 'min')} · {c.treatmentName}</span>
                              </div>
                              {c.recommendationReason && (
                                <div style={{
                                  fontSize: '11px',
                                  color: '#0d9488',
                                  backgroundColor: '#f0fdfa',
                                  padding: '4px 8px',
                                  borderRadius: '4px',
                                  border: '1px solid #ccfbf1',
                                  marginTop: '6px',
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: '4px'
                                }}>
                                  <Sparkles size={11} style={{ flexShrink: 0 }} />
                                  <span>{c.recommendationReason}</span>
                                  {c.recommendationScore ? <span style={{ marginLeft: 'auto', fontWeight: 600, color: '#047857' }}>({c.recommendationScore}đ)</span> : null}
                                </div>
                              )}
                            </div>
                          </div>

                          <div style={{ marginTop: '12px', paddingTop: '10px', borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'flex-end' }}>
                            <button
                              type="button"
                              id={`btn-reject-candidate-${c.candidateId}`}
                              onClick={(e) => {
                                e.stopPropagation();
                                handleRejectCandidate(c.candidateId);
                              }}
                              style={{
                                background: 'transparent',
                                border: 'none',
                                color: '#94a3b8',
                                fontSize: '12px',
                                cursor: 'pointer',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '4px',
                              }}
                              title={t('spa.rejectThisSlot', 'Dismiss this candidate')}
                            >
                              <XCircle size={14} />
                              <span>{t('spa.reject', 'Dismiss')}</span>
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* Pagination / Load More button */}
                {hasMore && (
                  <div style={{ textAlign: 'center', marginTop: '20px' }}>
                    <button
                      type="button"
                      id="btn-load-more-slots"
                      onClick={() => setVisibleCount((prev) => prev + 6)}
                      className="hsw-btn hsw-btn-secondary"
                      style={{
                        padding: '10px 24px',
                        fontSize: '13px',
                        fontWeight: 600,
                        borderRadius: '8px',
                        cursor: 'pointer',
                      }}
                    >
                      {t('spa.showMoreSlots', 'Show More Available Slots')} ({filteredAndSortedCandidates.length - visibleCount} {t('spa.remaining', 'remaining')})
                    </button>
                  </div>
                )}
              </section>
            )}

            {/* Alternative Candidates Section */}
            {alternativeCandidates.length > 0 && (
              <section className="spa-alternative-group" style={{ marginTop: candidates.length > 0 ? '28px' : '0' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px' }}>
                  <Sparkles size={18} style={{ color: '#0d9488' }} />
                  <h3 style={{ fontSize: '16px', fontWeight: 600, margin: 0, color: '#334155' }}>
                    {t('spa.alternativeOptions', 'Alternative Verified Candidates (Nearest Days)')}
                  </h3>
                </div>

                <div className="spa-candidates-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '16px' }}>
                  {alternativeCandidates.map((c) => {
                    const isSelected = selectedCandidate?.candidateId === c.candidateId;
                    return (
                      <div
                        key={c.candidateId}
                        className={`spa-candidate-card ${isSelected ? 'spa-candidate-card--selected' : ''}`}
                        onClick={() => setSelectedCandidate(c)}
                        id={`candidate-${c.candidateId}`}
                        style={{
                          border: isSelected ? '2px solid #0d9488' : '1px dashed #cbd5e1',
                          borderRadius: '10px',
                          padding: '16px',
                          cursor: 'pointer',
                          backgroundColor: isSelected ? '#f0fdfa' : '#fafafa',
                          boxShadow: isSelected ? '0 4px 12px rgba(13, 148, 136, 0.15)' : 'none',
                          transition: 'all 0.2s ease',
                          display: 'flex',
                          flexDirection: 'column',
                          justifyContent: 'space-between',
                        }}
                      >
                        <div>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '10px' }}>
                            <div>
                              <span style={{ fontSize: '11px', fontWeight: 600, color: '#0d9488', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                                {c.date}
                              </span>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginTop: '2px' }}>
                                <Clock size={15} style={{ color: '#0d9488' }} />
                                <span style={{ fontSize: '15px', fontWeight: 700, color: '#0f172a' }}>
                                  {c.startTime} – {c.endTime}
                                </span>
                              </div>
                            </div>
                            {isSelected && (
                              <span style={{ backgroundColor: '#0d9488', color: '#fff', borderRadius: '50%', padding: '2px', display: 'flex' }}>
                                <Check size={14} />
                              </span>
                            )}
                          </div>

                          <div style={{ fontSize: '13px', color: '#475569', display: 'flex', flexDirection: 'column', gap: '4px' }}>
                            <div><strong>{t('spa.therapist', 'Therapist')}:</strong> {c.therapistName}</div>
                            <div><strong>{t('spa.suite', 'Suite')}:</strong> {c.roomName}</div>
                            {c.recommendationReason && (
                              <div style={{
                                fontSize: '11px',
                                color: '#0d9488',
                                backgroundColor: '#f0fdfa',
                                padding: '3px 6px',
                                borderRadius: '4px',
                                border: '1px solid #ccfbf1',
                                marginTop: '4px',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '4px'
                              }}>
                                <Sparkles size={11} style={{ flexShrink: 0 }} />
                                <span>{c.recommendationReason}</span>
                              </div>
                            )}
                          </div>
                        </div>

                        <div style={{ marginTop: '12px', paddingTop: '10px', borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'flex-end' }}>
                          <button
                            type="button"
                            id={`btn-reject-candidate-${c.candidateId}`}
                            onClick={(e) => {
                              e.stopPropagation();
                              handleRejectCandidate(c.candidateId);
                            }}
                            style={{
                              background: 'transparent',
                              border: 'none',
                              color: '#94a3b8',
                              fontSize: '12px',
                              cursor: 'pointer',
                              display: 'flex',
                              alignItems: 'center',
                              gap: '4px',
                            }}
                            title={t('spa.rejectThisSlot', 'Dismiss this alternative')}
                          >
                            <XCircle size={14} />
                            <span>{t('spa.reject', 'Dismiss')}</span>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>
            )}

            {/* Exhaustion State (BR-M3-08) */}
            {isExhausted && (
              <div
                id="spa-alternatives-exhausted-panel"
                style={{
                  backgroundColor: '#fef2f2',
                  border: '1px solid #fecaca',
                  borderRadius: '12px',
                  padding: '32px 24px',
                  textAlign: 'center',
                  marginBottom: '24px',
                }}
              >
                <AlertCircle size={40} style={{ color: '#dc2626', margin: '0 auto 12px' }} />
                <h3 style={{ margin: '0 0 8px', color: '#991b1b', fontSize: '18px', fontWeight: 700 }}>
                  {t('spa.allAlternativesExhaustedTitle', 'All Alternative Candidates Exhausted / Declined')}
                </h3>
                <p style={{ margin: '0 0 20px', color: '#7f1d1d', fontSize: '14px', maxWidth: '540px', marginLeft: 'auto', marginRight: 'auto', lineHeight: 1.5 }}>
                  {t(
                    'spa.allAlternativesExhaustedDesc',
                    'No viable therapist and suite bundles remain within the search window for this treatment. In accordance with scheduling policy, you may cancel this reservation or adjust your stay constraints.'
                  )}
                </p>

                <div style={{ display: 'flex', gap: '12px', justifyContent: 'center', flexWrap: 'wrap' }}>
                  {rescheduleSessionId ? (
                    <button
                      type="button"
                      id="btn-cancel-exhausted-session"
                      className="hsw-btn"
                      onClick={handleDeclineAllAlternatives}
                      disabled={cancelling}
                      style={{
                        backgroundColor: '#dc2626',
                        color: '#fff',
                        padding: '10px 20px',
                        borderRadius: '8px',
                        border: 'none',
                        fontWeight: 600,
                        cursor: cancelling ? 'not-allowed' : 'pointer',
                      }}
                    >
                      {cancelling ? t('spa.cancelling', 'Cancelling...') : t('spa.cancelSession', 'Cancel Session Reservation')}
                    </button>
                  ) : (
                    <button
                      type="button"
                      id="btn-cancel-exhausted-session"
                      className="hsw-btn"
                      onClick={handleDeclineAllAlternatives}
                      style={{
                        backgroundColor: '#dc2626',
                        color: '#fff',
                        padding: '10px 20px',
                        borderRadius: '8px',
                        border: 'none',
                        fontWeight: 600,
                        cursor: 'pointer',
                      }}
                    >
                      {t('spa.cancelBookingAttempt', 'Cancel Booking Attempt')}
                    </button>
                  )}
                  <button
                    type="button"
                    id="btn-adjust-criteria"
                    className="hsw-btn hsw-btn-secondary"
                    onClick={() =>
                      navigate(
                        `/customer/spa/book?treatment=${treatmentId}${
                          rescheduleSessionId ? `&reschedule=${rescheduleSessionId}` : ''
                        }`
                      )
                    }
                    style={{ padding: '10px 20px' }}
                  >
                    {t('spa.adjustCriteria', 'Adjust Date & Time Constraints')}
                  </button>
                </div>
              </div>
            )}
          </div>

          {/* Sidebar / Bottom Action Drawer */}
          {!isExhausted && (
            <div className="spa-alt-sidebar" style={{ minWidth: '280px', marginTop: '20px' }}>
              <div style={{ backgroundColor: 'var(--surface)', border: '1px solid var(--border-subtle)', borderRadius: '12px', padding: '20px', position: 'sticky', top: '20px' }}>
                <h3 style={{ margin: '0 0 14px', fontSize: '16px' }}>{t('spa.selectedCandidateBundle', 'Selected Candidate')}</h3>

                {selectedCandidate ? (
                  <div style={{ fontSize: '14px', display: 'flex', flexDirection: 'column', gap: '10px', marginBottom: '18px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.date', 'Date')}</span>
                      <strong>{selectedCandidate.date}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.time', 'Time')}</span>
                      <strong>{selectedCandidate.startTime} – {selectedCandidate.endTime}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.therapist', 'Therapist')}</span>
                      <strong>{selectedCandidate.therapistName}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.suite', 'Suite')}</span>
                      <strong>{selectedCandidate.roomName}</strong>
                    </div>

                    <div style={{ backgroundColor: '#f0fdfa', border: '1px solid #ccfbf1', borderRadius: '6px', padding: '10px', fontSize: '12px', color: '#0f766e', marginTop: '6px' }}>
                      <Check size={14} style={{ display: 'inline', marginRight: '4px', verticalAlign: 'text-bottom' }} />
                      {t('spa.indivisibleConfirmed', 'Indivisible bundle matched by scheduling engine.')}
                    </div>
                  </div>
                ) : (
                  <div style={{ color: '#94a3b8', fontSize: '13px', fontStyle: 'italic', marginBottom: '18px' }}>
                    {t('spa.pleaseSelectCandidate', 'Please select one candidate bundle above to continue.')}
                  </div>
                )}

                <button
                  className="hsw-btn hsw-btn-primary"
                  disabled={!selectedCandidate}
                  onClick={handleSelectAndProceed}
                  id="btn-proceed-to-confirm"
                  style={{
                    width: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: '8px',
                    padding: '12px',
                    fontWeight: 600,
                    opacity: selectedCandidate ? 1 : 0.6,
                    cursor: selectedCandidate ? 'pointer' : 'not-allowed',
                  }}
                >
                  <span>{t('spa.proceedToConfirmation', 'Proceed to Confirmation')}</span>
                  <ArrowRight size={16} />
                </button>

                <button
                  type="button"
                  id="btn-decline-all-alternatives"
                  className="hsw-btn"
                  onClick={handleDeclineAllAlternatives}
                  disabled={cancelling}
                  style={{
                    width: '100%',
                    marginTop: '10px',
                    padding: '10px',
                    background: '#fff',
                    border: '1px solid #fecaca',
                    color: '#dc2626',
                    borderRadius: '8px',
                    fontSize: '13px',
                    fontWeight: 500,
                    cursor: cancelling ? 'not-allowed' : 'pointer',
                  }}
                >
                  {cancelling ? t('spa.cancelling', 'Cancelling...') : t('spa.declineAllAlternatives', 'Decline All Alternatives')}
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};
